-- Music Appreciation and Worship Arts final module. Run seed_pe_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'music-appreciation-worship-arts';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Listening and Performance Portfolio$j$, $j${"prompt": "Create a portfolio of at least 600 words with your listening journal and practice journal attached, and prepare a short presentation of its main ideas. Write complete sentences and label each part. Psalm 33:3 says, Sing unto him a new song; play skilfully with a loud noise.\n\nPart 1: Elements of Music. Choose two contrasting pieces and describe each using rhythm, melody, harmony, tempo, dynamics, form and timbre.\nPart 2: Scripture and Worship. Explain three purposes of singing in church from the Bible, with references, and five marks of good worship music.\nPart 3: History. Choose one period of Western music and one American tradition. Describe the features, a key person and a lasting contribution of each.\nPart 4: Skills. Attach your practice journal with at least ten entries over at least four weeks. Report your goals, what improved and what you will work on next. Include a recorded or live performance of a short song, hymn or rhythm for a parent, guardian or teacher, and a short reflection.\nPart 5: Wise Listening and Honesty. Evaluate one song in any style using the five wise listening questions, and explain copyright, public domain and why honesty matters in sharing music.\nPart 6: Service and Character. Describe a servant heart for worship leading and one way you will serve with music, with adult permission and supervision.\nPart 7: Listening Journal. Attach at least ten entries, including live or recorded pieces from at least four different styles or periods.\nPart 8: Presentation Plan. Write a three part outline and an opening line for a three minute talk.", "rubric": "100 points. Part 1, elements of music: 15 points. Part 2, Scripture and worship: 10 points. Part 3, history: 10 points. Part 4, skills, practice journal and performance: 20 points. Part 5, wise listening and honesty: 10 points. Part 6, service and character: 5 points. Part 7, listening journal: 15 points. Part 8, presentation plan: 5 points. Grammar, conventions and respectful tone: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Listening and Performance Portfolio$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Music Appreciation and Worship Arts$j$, $j${"questions": [{"q": "The steady pulse in music is called the:", "options": ["Beat", "Melody", "Timbre", "Texture"]}, {"q": "A quarter note in 4/4 time gets:", "options": ["One beat", "Two beats", "Four beats", "Half a beat"]}, {"q": "Piano as a dynamic mark means:", "options": ["Fast", "Soft", "Slow", "Loud"]}, {"q": "Brass instruments make sound when the player:", "options": ["Buzzes the lips into a metal mouthpiece", "Blows over a reed", "Plucks strings", "Strikes a drum"]}, {"q": "Second Chronicles 5:13 says the trumpeters and singers were:", "options": ["Silent", "Divided in opinion", "Out of tune", "As one, making one sound in praise"]}, {"q": "Psalm 47:7 says to sing praises:", "options": ["Only at night", "With understanding", "Only alone", "Without words"]}, {"q": "Ephesians 5:19 mentions psalms, hymns and:", "options": ["Silence", "Poems", "Drums", "Spiritual songs"]}, {"q": "Gregorian chant is a single melody sung:", "options": ["With a full orchestra", "Without instruments or harmony", "Only by children", "With electric guitars"]}, {"q": "Soli Deo Gloria means:", "options": ["Play loudly", "A new song", "To God alone be the glory", "The end of the piece"]}, {"q": "The father of English hymnody is:", "options": ["Verdi", "Mozart", "Gershwin", "Isaac Watts"]}, {"q": "Spirituals were created mainly by:", "options": ["Enslaved African Americans", "Monks in monasteries", "Renaissance court composers", "Radio engineers"]}, {"q": "The lines of the treble clef, from bottom to top, are:", "options": ["A C E G", "F A C E", "G B D F A", "E G B D F"]}, {"q": "Singers can protect their voices by:", "options": ["Avoiding water", "Shouting often", "Warming up, drinking water and resting a sore voice", "Singing through pain"]}, {"q": "Copyright protection in the United States begins:", "options": ["When a work is created and fixed in a form such as a recording or score", "Never", "Only after 50 years", "Only after a fee is paid"]}, {"q": "Philippians 4:8 teaches listeners to think on things that are:", "options": ["True, honest, just, pure and lovely", "Loud and fast", "Expensive", "Popular and new"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Music Appreciation and Worship Arts$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,1,0,3,1,3,1,2,3,0,3,2,0,0}'::int[], array[$j$Rhythm moves over the beat.$j$,$j$The quarter note is the beat note in 4/4.$j$,$j$Piano is soft and forte is loud.$j$,$j$The trumpet and trombone are brass.$j$,$j$Unity and skill belong in worship.$j$,$j$Think about what you sing.$j$,$j$Paul names three kinds of songs.$j$,$j$Chant is monophonic.$j$,$j$Bach often wrote S D G on his scores.$j$,$j$Watts wrote hundreds of hymns.$j$,$j$They drew on the Bible and African musical traditions.$j$,$j$Every Good Boy Does Fine.$j$,$j$Pain is a signal to stop.$j$,$j$Registration helps but protection is automatic.$j$,$j$The verse gives a test for wise listening.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Music Appreciation and Worship Arts$j$ on conflict (item_id) do nothing;
end
$seed$;
